def parse_range(header, size):
    """
    Parse an RFC 7233 Range header for bytes.

    Args:
        header (str): The value of the Range header (e.g., "bytes=0-499").
        size (int): The total size of the resource in bytes.

    Returns:
        list of tuple: List of (start, end) inclusive byte offsets.
        None: If the header is unsatisfiable (all ranges are invalid).
    """
    if not header.startswith("bytes="):
        return None

    ranges_str = header[6:]  # Remove "bytes="
    if not ranges_str:
        return None

    ranges = []
    parts = ranges_str.split(",")

    for part in parts:
        part = part.strip()
        if not part:
            continue

        if part.startswith("-"):
            # Suffix range: e.g., "-500"
            if part == "-":
                # Invalid suffix range without length
                continue

            try:
                suffix_length = int(part[1:])
            except ValueError:
                continue

            if suffix_length <= 0:
                continue

            if suffix_length > size:
                # Suffix length larger than resource yields the whole resource
                start = 0
                end = size - 1
            else:
                start = size - suffix_length
                end = size - 1

            ranges.append((start, end))

        elif "-" in part:
            # Normal range: e.g., "0-499" or "500-"
            try:
                start_str, end_str = part.split("-", 1)
                start = int(start_str)

                if end_str == "":
                    # Range to the end
                    if start >= size:
                        # Start is at or past size -> unsatisfiable
                        continue
                    end = size - 1
                else:
                    end = int(end_str)
                    if start > end:
                        # Invalid range (start > end)
                        continue
                    # Clamp end to size - 1
                    end = min(end, size - 1)

                if start < 0:
                    continue

                ranges.append((start, end))

            except ValueError:
                continue
        else:
            # Malformed (no dash)
            continue

    if not ranges:
        return None

    return ranges
```

