from typing import Union, List, Tuple

def tokenize(expr: str) -> List[str]:
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue
        if expr[i] in '+-*/%()':
            tokens.append(expr[i])
            i += 1
        elif expr[i] == '.':
            # Check for decimal
            if i + 1 < len(expr) and expr[i+1].isdigit():
                j = i + 1
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                tokens.append(expr[i:j])
                i = j
            else:
                raise ValueError("Invalid decimal format")
        elif expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(expr[i:j])
            i = j
        else:
            raise ValueError(f"Invalid character: {expr[i]}")
    return tokens

def parse_unary(tokens: List[str], pos: int) -> Tuple[Union[int, float], int]:
    if pos >= len(tokens):
        raise ValueError("Unexpected end of expression")

    if tokens[pos] == '-':
        val, new_pos = parse_unary(tokens, pos + 1)
        return -val, new_pos
    if tokens[pos] == '+':
        val, new_pos = parse_unary(tokens, pos + 1)
        return val, new_pos

    # Number
    num_str = tokens[pos]
    if '.' in num_str:
        val = float(num_str)
    else:
        val = int(num_str)
    return val, pos + 1

def parse_power(tokens: List[str], pos: int) -> Tuple[Union[int, float], int]:
    if pos >= len(tokens):
        raise ValueError("Unexpected end of expression")

    # Handle unary minus/plus before power
    val, pos = parse_unary(tokens, pos)

    if pos < len(tokens) and tokens[pos] == '**':
        val2, pos = parse_power(tokens, pos + 1)
        val = val ** val2

    return val, pos

def parse_multiply(tokens: List[str], pos: int) -> Tuple[Union[int, float], int]:
    if pos >= len(tokens):
        raise ValueError("Unexpected end of expression")

    val, pos = parse_power(tokens, pos)

    while pos < len(tokens) and tokens[pos] in ('*', '/', '%'):
        op = tokens[pos]
        pos += 1
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")
        val2, pos = parse_power(tokens, pos)

        if op == '*':
            val = val * val2
        elif op == '/':
            if val2 == 0:
                raise ValueError("Division by zero")
            val = val / val2
        elif op == '%':
            if val2 == 0:
                raise ValueError("Modulo by zero")
            val = val % val2

    return val, pos

def parse_add(tokens: List[str], pos: int) -> Tuple[Union[int, float], int]:
    if pos >= len(tokens):
        raise ValueError("Unexpected end of expression")

    val, pos = parse_multiply(tokens, pos)

    while pos < len(tokens) and tokens[pos] in ('+', '-'):
        op = tokens[pos]
        pos += 1
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")
        val2, pos = parse_multiply(tokens, pos)

        if op == '+':
            val = val + val2
