def deep_copy(obj):
    seen = {}

    def copy_value(o):
        # Base cases: immutable scalars are returned as-is
        if isinstance(o, (str, int, float, bool, type(None))):
            return o

        # Handle cycles by checking if we've already started copying this object
        if id(o) in seen:
            return seen[id(o)]

        # Create a placeholder for the object being copied to break cycles
        seen[id(o)] = []

        # Determine the type and create a new container
        if isinstance(o, dict):
            new_obj = {}
            for k, v in o.items():
                new_obj[copy_value(k)] = copy_value(v)
            seen[id(o)] = new_obj
            return new_obj

        elif isinstance(o, list):
            new_obj = []
            for item in o:
                new_obj.append(copy_value(item))
            seen[id(o)] = new_obj
            return new_obj

        elif isinstance(o, set):
            new_obj = set()
            for item in o:
                new_obj.add(copy_value(item))
            seen[id(o)] = new_obj
            return new_obj

        elif isinstance(o, tuple):
            new_obj = tuple(copy_value(item) for item in o)
            seen[id(o)] = new_obj
            return new_obj

        else:
            # Fallback for other types, though problem statement implies only specific types
            return o

    return copy_value(obj)

