class Spreadsheet:
    def __init__(self):
        self._values = {}  # cell -> raw value (number or formula string)
        self._deps = {}    # cell -> set of cells it depends on
        self._rev_deps = {} # cell -> set of cells that depend on it

    def _parse_formula(self, formula_str):
        """Parse a formula string into an AST-like structure for evaluation."""
        formula_str = formula_str.strip()
        if not formula_str.startswith('='):
            raise ValueError("Formula must start with '='")

        expr = formula_str[1:]
        tokens = self._tokenize(expr)
        return self._parse_expr(tokens, 0)[0]

    def _tokenize(self, expr):
        tokens = []
        i = 0
        while i < len(expr):
            if expr[i].isspace():
                i += 1
                continue
            if expr[i] in '+-*/':
                tokens.append(('OP', expr[i]))
                i += 1
            elif expr[i].isdigit() or (expr[i] == '-' and i+1 < len(expr) and expr[i+1].isdigit()):
                j = i
                if expr[i] == '-':
                    j += 1
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                tokens.append(('NUM', int(expr[i:j])))
                i = j
            elif expr[i].isalpha() or (expr[i] == '$' or expr[i] == '&'):
                # Cell reference: optional $, then letters, then optional numbers
                j = i
                if expr[j] == '$':
                    j += 1
                while j < len(expr) and (expr[j].isalpha() or expr[j].isdigit()):
                    j += 1
                tokens.append(('CELL', expr[i:j]))
                i = j
            else:
                raise ValueError(f"Unexpected character: {expr[i]}")
        return tokens

    def _parse_expr(self, tokens, pos):
        """Parse expression with precedence: * before + and -"""
        left, new_pos = self._parse_term(tokens, pos)
        while new_pos < len(tokens) and tokens[new_pos][0] == 'OP' and tokens[new_pos][1] in '+-':
            op = tokens[new_pos][1]
            new_pos += 1
            right, new_pos = self._parse_term(tokens, new_pos)
            left = (op, left, right)
        return left, new_pos

    def _parse_term(self, tokens, pos):
        """Parse multiplication terms"""
        left, new_pos = self._parse_factor(tokens, pos)
        while new_pos < len(tokens) and tokens[new_pos][0] == 'OP' and tokens[new_pos][1] == '*':
            op = tokens[new_pos][1]
            new_pos += 1
            right, new_pos = self._parse_factor(tokens, new_pos)
            left = (op, left, right)
        return left, new_pos

    def _parse_factor(self, tokens, pos):
        """Parse a single factor (number or cell reference)"""
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")
        token_type, token_val = tokens[pos]
        if token_type == 'NUM':
            return (token_val, pos + 1)
        elif token_type == 'CELL':
            return (token_val, pos + 1)
        else:
            raise ValueError(f"Unexpected token: {token_type}")

    def _evaluate(self, cell, visited=None):
        """Evaluate a cell, handling cycles by detecting back-edges."""
        if visited is None:
            visited = set()

        if cell in visited:
            raise ValueError("Circular reference detected")

        if cell not in self._values:
            return 0

        raw_value = self._values[cell]

        if not isinstance(raw_value, str) or not raw_value.startswith('='):
            return raw_value

        # Parse and evaluate the formula
        ast = self._parse_formula(raw_value)
        result = self._eval_ast(ast, visited)
        return result

    def _eval_ast(self, ast, visited):
        if isinstance(ast, int):
            return ast
        elif isinstance(ast, tuple) and len(ast) == 3:
            op, left, right = ast
            if op == '+':
                return self._eval_ast(left, visited) + self._eval_ast(right, visited)
            elif op == '-':
                return self._eval_ast(left, visited) - self._eval_ast(right, visited)
            elif op == '*':
                return self._eval_ast(left, visited) * self._eval_ast(right, visited)
            else:
                raise ValueError(f"Unknown operator: {op}")
        else:
            # It's a cell reference
            if ast in visited:
                raise ValueError("Circular reference detected")
            visited.add(ast)
            try:
                result = self._evaluate(ast, visited)
            finally:
                visited.remove(ast)
            return result

    def _get_dependencies(self, cell, visited=None):
        """Get all cells that this cell depends on (transitively)."""
        if visited is None:
            visited = set()

        if cell in visited:
            return set()

        visited.add(cell)
        deps = set()

        if cell in self._values:
