    // If source is undefined, do not overwrite
    if (sourceVal === undefined) {
      if (targetVal !== undefined) {
        result[key] = targetVal;
      }
      continue;
    }

    // If source is null, it overwrites
    if (sourceVal === null) {
      result[key] = null;
      continue;
    }

    // If target is undefined, use source
    if (targetVal === undefined) {
      result[key] = sourceVal;
