  if (typeof size !== 'number' || size <= 0) {
    throw new Error('size must be a positive integer');
  }

  return async function* () {
    const buffer = [];
    let iterator;

    try {
      iterator = typeof source[Symbol.asyncIterator] === 'function'
        ? source[Symbol.asyncIterator]()
        : (typeof source[Symbol.iterator] === 'function'
            ? source[Symbol.iterator]()
            : (async function* () { yield* source; })()[Symbol.asyncIterator]());

      while (true) {
        // Pull up to `size` items, but stop if the consumer has already asked for a chunk
        // We use a loop that fetches one by one until we hit the limit or the stream ends.
        // However, to ensure laziness (not pulling more than needed for the current chunk),
        // we must check if the consumer is waiting. Since we are inside an async generator,
        // the yield happens when the consumer awaits. We can't easily peek without yielding.
        // Strategy: Pull items one by one, yield the chunk when we have `size` items or the stream ends.
        // But we need to handle the case where the stream ends mid-chunk.

        // To strictly adhere to "pulls at most size items ahead", we accumulate up to `size`.
        // If the stream ends, we yield what we have.
        // If the consumer stops (via return), we must clean up.

        while (buffer.length < size) {
          const next = await iterator.next();
          if (next.done) {
            break;
          }
          buffer.push(next.value);
        }

        if (buffer.length === 0) {
          // Stream ended and we have no items for this chunk
          break;
        }

        yield buffer;
        buffer.length = 0;
      }
    } finally {
      if (iterator && typeof iterator.return === 'function') {
        await iterator.return();
      }
    }
