module.exports = function zipLongest(fill, ...iterables) {
  if (iterables.length === 0) {
    return (function* () {})();
  }

  const iterators = iterables.map(it => {
    const iter = typeof it[Symbol.iterator] === 'function' ? it[Symbol.iterator]().next : () => ({ done: true, value: undefined });
    return { iter, done: false };
  });

  return (function* () {
    while (true) {
      const currentValues = iterators.map(({ iter, done }) => {
        if (done) {
          return fill;
        }
        const result = iter();
        if (result.done) {
          // Mark as done immediately after pulling the last item
          iterators[iterators.indexOf({ iter, done })].done = true;
          return fill;
        }
        return result.value;
      });

      // Check if all are done
      if (currentValues.every(v => v === fill && iterators.every(i => i.done))) {
        break;
      }

      yield currentValues;
    }
  })();
};

