export type Config = {
  name: string;
  age?: number;
  active: boolean;
};

export type RequiredKeys<T> = {
  [K in keyof T]: T[K] extends undefined ? never : K;
}[keyof T];

export type OptionalKeys<T> = {
  [K in keyof T]: T[K] extends undefined ? K : never;
}[keyof T];

export type BuilderState<T> = {
  data: Partial<T>;
  requiredKeys: Set<keyof T>;
  optionalKeys: Set<keyof T>;
};

export function builder<Config extends Record<string, unknown>>() {
  const state: BuilderState<Config> = {
    data: {} as Partial<Config>,
    requiredKeys: new Set<keyof Config>(Object.keys(Config) as unknown as (keyof Config)[]).filter(
      (k): k is keyof Config => (Config as any)[k] !== undefined
    ),
    optionalKeys: new Set<keyof Config>(Object.keys(Config) as unknown as (keyof Config)[]).filter(
      (k): k is keyof Config => (Config as any)[k] === undefined
    ),
  };

  const set = <K extends keyof Config>(key: K, value: Config[K]) => {
    if (!state.requiredKeys.has(key) && !state.optionalKeys.has(key)) {
      // This check is primarily for runtime safety, but TypeScript will catch unknown keys at compile time
      throw new Error(`Unknown key: ${key}`);
    }
    state.data[key] = value;
    return set;
  };

  const build = () => {
    const missingRequired = state.requiredKeys.filter((k) => state.data[k] === undefined);
    if (missingRequired.length > 0) {
      throw new Error(`Missing required keys: ${missingRequired.join(', ')}`);
    }
    return state.data as Config;
  };

  return {
    set,
    build,
  };
}

export type Builder<Config> = ReturnType<typeof builder<Config>>;

