export type RouteParams<T extends Record<string, string>> = {
  [K in keyof T]: T[K] extends `:${infer Name}` ? Name : never;
}[keyof T];

export type RoutePath<T extends Record<string, string>> = {
  [K in keyof T]: T[K] extends `:${infer _}` ? string : never;
}[keyof T];

export type RouteHandler<T extends Record<string, string>> = T extends Record<string, never>
  ? () => string
  : <P extends RouteParams<T>>(params: P) => string;

export function defineRoutes<T extends Record<string, string>>(
  routes: T
): {
  [K in keyof T]: T[K] extends `:${infer _}`
    ? RouteHandler<T[K]>
    : () => string;
} {
  const handlers: any = {};

  for (const [name, path] of Object.entries(routes)) {
    const paramNames = path.match(/:(\w+)/g)?.map((m) => m.slice(1)) || [];

    if (paramNames.length === 0) {
      handlers[name] = () => path;
    } else {
      handlers[name] = (params: Record<string, string>) => {
        const result = path;
        for (const [key, value] of Object.entries(params)) {
          const regex = new RegExp(`:\\${key}`, 'g');
          result = result.replace(regex, value);
        }
        return result;
      };
    }
  }

  return handlers as any;
}

